<?php require_once 'includes/db.php'; $id=(int)($_GET['id']??0); $item=['identificacao'=>'','cep'=>'','logradouro'=>'','numero'=>'','complemento'=>'','bairro'=>'','cidade'=>'','estado'=>'']; if($id){$s=$pdo->prepare('SELECT * FROM enderecos WHERE id=?');$s->execute([$id]);$item=$s->fetch()?:$item;} $pageTitle=$id?'Editar endereço':'Novo endereço'; require 'includes/header.php'; ?><div class="page-heading"><h1 class="h3"><?=$pageTitle?></h1><a href="enderecos.php" class="btn btn-outline-secondary">Voltar</a></div><form class="card p-4" method="post" action="save.php"><input type="hidden" name="tipo" value="endereco"><input type="hidden" name="id" value="<?=$id?>"><div class="row"><?php $fields=['identificacao'=>'Identificação (origem/destino) [ex.: Depósito]','cep'=>'CEP','logradouro'=>'Logradouro','numero'=>'Número','complemento'=>'Complemento','bairro'=>'Bairro','cidade'=>'Cidade','estado'=>'UF']; foreach($fields as $k=>$label): ?><div class="col-md-<?=in_array($k,['logradouro','identificacao'])?'6':'4'?> mb-3"><label class="form-label <?=in_array($k,['identificacao','logradouro','cidade','estado'])?'required':''?>"><?=e($label)?></label><input class="form-control" name="<?=$k?>" value="<?=e($item[$k])?>" <?=in_array($k,['identificacao','logradouro','cidade','estado'])?'required':''?> maxlength="150"></div><?php endforeach; ?></div><button class="btn btn-primary align-self-start">Salvar endereço</button></form><?php require 'includes/footer.php'; ?>
